// v0.17 transport coordinator contract (T-1583~T-1612)
test('coordinator statuses are fixed', () => assert.deepEqual(a.AUDIT_COORDINATOR_STATUS, ['ready', 'committed', 'cancelled', 'timeout', 'disposed']));
