test('coordinator recover commits queue', () => { const q = a.createAgentReadOnlyAuditTransportQueue(); q.enqueue({}); const c = a.createAgentReadOnlyAuditTransportCoordinator(q); assert.equal(c.recover().status, 'committed'); });
